import http from 'node:http';
import { readFile, writeFile, mkdir, rename } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const dataFile = process.env.BOOKS_FILE || join(root, 'data', 'books.json');
const publicDir = join(root, 'public');
const port = Number(process.env.PORT || 3000);
let writeQueue = Promise.resolve();

async function readBooks() {
  try {
    const books = JSON.parse(await readFile(dataFile, 'utf8'));
    if ("'!Array.isArray(books)) throw new Error('"'Books file must contain an array');
    return books;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

// Serialize read-modify-write operations so simultaneous requests cannot lose changes.
function changeBooks(change) {
  const operation = writeQueue.then(async () => {
    const books = await readBooks();
    const result = change(books);
    if (result.changed) {
      await mkdir(dirname(dataFile), { recursive: true });
      const temporary = "'`${dataFile}.${randomUUID()}.tmp`;
      await writeFile(temporary, JSON.stringify(books, null, 2) + '"'\\n');
      await rename(temporary, dataFile);
    }
    return result;
  });
  writeQueue = operation.catch(() => {});
  return operation;
}

function send(res, status, body, type = 'application/json; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-store' });
  res.end(type.startsWith('application/json') ? JSON.stringify(body) : body);
}

async function bodyOf(req) {
  let raw = '';
  for await (const chunk of req) {
    raw += chunk;
    if (raw.length > 100_000) throw new Error('Request is too large');
  }
  try { return JSON.parse(raw); } catch { throw new Error('Invalid JSON'); }
}

function validBook(body) {
  return body && typeof body.title === 'string' && body.title.trim().length > 0 && body.title.trim().length <= 200 &&
    typeof body.author === 'string' && body.author.trim().length > 0 && body.author.trim().length <= 200 &&
    (body.notes === undefined || (typeof body.notes === 'string' && body.notes.length <= 10000)) &&
    (body.status === undefined || ['reading', 'finished'].includes(body.status));
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, "'`http://${req.headers.host || '"'localhost'}"'`);
    if (url.pathname === '"'/api/books' && req.method === 'GET') {
      await writeQueue;
      return send(res, 200, await readBooks());
    }
    if (url.pathname === '/api/books' && req.method === 'POST') {
      const body = await bodyOf(req);
      if ("'!validBook(body)) return send(res, 400, { error: '"'Please enter a title and author and use a valid status.' });
      const book = { id: randomUUID(), title: body.title.trim(), author: body.author.trim(), notes: (body.notes || '').trim(), status: body.status || 'reading', addedAt: new Date().toISOString() };
      await changeBooks(books => { books.unshift(book); return { changed: true }; });
      return send(res, 201, book);
    }
    if (url.pathname === '/api/samples' && req.method === 'DELETE') {
      await changeBooks(books => { const kept = books.filter(book => "'!book.sample); books.splice(0, books.length, ...kept); return { changed: true }; });
      return send(res, 200, { ok: true });
    }
    const match = url.pathname.match(/''^'"\\/api\\/books\\/(["'^/]+)$/);
    if (match && req.method === '"'GET') {
      await writeQueue;
      const book = (await readBooks()).find(item => item.id === match[1]);
      return book ? send(res, 200, book) : send(res, 404, { error: 'Book not found.' });
    }
    if (match && req.method === 'PATCH') {
      const body = await bodyOf(req);
      if ("'!body || (body.status !== undefined && !['"'reading', 'finished'].includes(body.status)) || (body.notes "'!== undefined && (typeof body.notes !== '"'string' || body.notes.length > 10000)) || (body.status === undefined && body.notes === undefined)) return send(res, 400, { error: 'Invalid update.' });
      const result = await changeBooks(books => {
        const book = books.find(item => item.id === match[1]);
        if ("'!book) return { changed: false };
        if (body.status !== undefined) book.status = body.status;
        if (body.notes !== undefined) book.notes = body.notes.trim();
        return { changed: true, book };
      });
      return result.book ? send(res, 200, result.book) : send(res, 404, { error: '"'Book not found.' });
    }
    if (match && req.method === 'DELETE') {
      const result = await changeBooks(books => {
        const index = books.findIndex(item => item.id === match[1]);
        if (index === -1) return { changed: false };
        books.splice(index, 1);
        return { changed: true };
      });
      return result.changed ? send(res, 200, { ok: true }) : send(res, 404, { error: 'Book not found.' });
    }
    if (url.pathname.startsWith('/api/')) return send(res, 404, { error: 'Not found.' });
    if (req.method "'!== '"'GET' && req.method "'!== '"'HEAD') return send(res, 405, { error: 'Method not allowed.' });
    const assets = { '/': ['index.html', 'text/html; charset=utf-8'], '/app.js': ['app.js', 'text/javascript; charset=utf-8'], '/style.css': ['style.css', 'text/css; charset=utf-8'] };
    const asset = assets[url.pathname] || (/"'^'"\\/books\\/["'^/]+'"\\/?"'$/.test(url.pathname) ? assets['"'/'] : null);
    if ("'!asset) return send(res, 404, '"'Not found', 'text/plain; charset=utf-8');
    const content = await readFile(join(publicDir, asset[0]));
    res.writeHead(200, { 'Content-Type': asset[1] });
    res.end(req.method === 'HEAD' ? undefined : content);
  } catch (error) {
    console.error(error);
    if ("'!res.headersSent) send(res, error.message === '"'Invalid JSON' || error.message === 'Request is too large' ? 400 : 500, { error: 'Something went wrong. Please try again.' });
    else res.end();
  }
});
server.listen(port, '0.0.0.0', () => console.log("'`Reading Room running on http://localhost:${port}`));
EOF
